import React from 'react';
import { useSearchParams } from 'react-router-dom';
import { QrCode, ShieldCheck, Smartphone, SmartphoneNfc } from 'lucide-react';
import { PosCheckoutPage } from './PosCheckoutPage';

export const PosNfcMobile = () => {
  const [searchParams] = useSearchParams();
  const checkoutId = searchParams.get('checkout');

  if (checkoutId) {
    return <PosCheckoutPage checkoutIdOverride={checkoutId} presentation="mobile" />;
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-[#f4f5f7] p-5 text-slate-950">
      <main className="w-full max-w-md rounded-[36px] border border-slate-200 bg-white p-7 text-center shadow-2xl shadow-slate-950/10 sm:p-9">
        <div className="mx-auto flex h-20 w-20 items-center justify-center rounded-[28px] bg-slate-950 text-white">
          <SmartphoneNfc className="h-10 w-10" />
        </div>
        <span className="mt-6 inline-flex items-center gap-2 rounded-full bg-slate-100 px-4 py-2 text-xs font-bold uppercase tracking-[0.14em] text-slate-600">
          <Smartphone className="h-4 w-4" /> Mobile checkout
        </span>
        <h1 className="mt-4 text-3xl font-black tracking-tight">Open a live till code</h1>
        <p className="mt-3 text-sm leading-6 text-slate-500">
          Start a sale on the POS terminal and scan its current Mobile Pay QR code. Every code is linked to one exact order and expires automatically.
        </p>
        <div className="mt-7 grid grid-cols-2 gap-3 text-left">
          <div className="rounded-[22px] bg-slate-50 p-4"><QrCode className="h-5 w-5" /><p className="mt-3 text-sm font-bold">Order-bound QR</p><p className="mt-1 text-xs leading-5 text-slate-500">No amount is entered on the phone.</p></div>
          <div className="rounded-[22px] bg-slate-50 p-4"><ShieldCheck className="h-5 w-5" /><p className="mt-3 text-sm font-bold">Stripe secured</p><p className="mt-1 text-xs leading-5 text-slate-500">Wallets appear when supported.</p></div>
        </div>
        <p className="mt-7 text-xs leading-5 text-slate-400">
          Web checkout supports Apple Pay, Google Pay and cards when enabled by the merchant. Accepting a physical card by tapping it on the owner&apos;s phone requires Wersee&apos;s native Stripe Terminal app.
        </p>
      </main>
    </div>
  );
};
